import Image from 'next/image';
import { cn } from '@/lib/utils';

/** Artwork in public/svg (generated by docs/brand/logo/gen_logo.py); sizes are the viewBox ratios. */
const VARIANTS = {
  /** Tile + "Jarda | جردة" on one line. */
  full: { light: '/svg/logo-full.svg', dark: '/svg/logo-full-dark.svg', ratio: 270 / 80 },
  /** Tile above "Jarda" above "جردة". */
  stacked: { light: '/svg/logo-stacked.svg', dark: '/svg/logo-stacked-dark.svg', ratio: 122 / 184 },
  /** The square tile only (the same file on light and dark backgrounds). */
  icon: { light: '/svg/logo-icon.svg', dark: '/svg/logo-icon.svg', ratio: 1 },
} as const;

interface BrandLogoProps {
  variant?: keyof typeof VARIANTS;
  /** Rendered height in px; the width follows the artwork. */
  height: number;
  /** The product name in the reader's language (the artwork itself shows both scripts). */
  alt: string;
  /** `light`/`dark` force one artwork (e.g. on a coloured panel); `auto` follows the theme. */
  tone?: 'auto' | 'light' | 'dark';
  className?: string;
  priority?: boolean;
}

/** The Jarda logo with its light/dark artwork swapped by the theme. */
export function BrandLogo({
  variant = 'full',
  height,
  alt,
  tone = 'auto',
  className,
  priority,
}: BrandLogoProps): JSX.Element {
  const art = VARIANTS[variant];
  const width = Math.round(height * art.ratio);
  const common = { width, height, priority, style: { width, height } };
  if (tone !== 'auto' || art.light === art.dark) {
    const src = tone === 'dark' ? art.dark : art.light;
    return <Image src={src} alt={alt} className={cn('shrink-0', className)} {...common} />;
  }
  return (
    <>
      <Image
        src={art.light}
        alt={alt}
        className={cn('shrink-0 dark:hidden', className)}
        {...common}
      />
      <Image
        src={art.dark}
        alt=""
        aria-hidden
        className={cn('hidden shrink-0 dark:block', className)}
        {...common}
      />
    </>
  );
}
